fn queue_after(values:&[i32],remove:usize)->Vec<i32> {
    let mut queue=std::collections::VecDeque::new();
    for &n in values {
        queue.push_back(n);
    }
    for _ in 0..remove {
        if queue.pop_front().is_none() {
            break;
        }
    }
    queue.into_iter().collect()
}

fn partial_sums(values: &[i32]) -> Vec<i32> {
    let mut total=0;
    let mut out=Vec::new();
    for &value in values {
        total+=value;
        out.push(total);
    }
    out
}

fn count_word(s: &str, wanted: &str) -> usize {
    let mut counts=std::collections::HashMap::new();
    for word in s.split_whitespace() {
        *counts.entry(word).or_insert(0usize)+=1;
    }
    counts.get(wanted).copied().unwrap_or(0)
}

fn insertion_steps(values:&[i32],steps:usize)->Vec<i32> {
    let mut out=values.to_vec();
    for i in 1..out.len().min(steps.saturating_add(1)) {
        let key=out[i];
        let mut j=i;
        while j>0&&out[j-1]>key {
            out[j]=out[j-1];
            j-=1;
        }
        out[j]=key;
    }
    out
}

fn sum_generic<T>(values:&[T])->T where T:Copy+Default+std::ops::Add<Output=T> {
    let mut total=T::default();
    for &value in values {
        total=total+value;
    }
    total
}

