fn is_prime(n: u32) -> bool {
    if n<2 {
        return false;
    }
    let mut d=2;
    while d<=n/d {
        if n%d==0 {
            return false;
        }
        d+=1;
    }
    true
}

enum Tree {
    Empty,Node(Box<Tree>,Box<Tree>)
}
fn tree_depth(tree:&Tree)->usize {
    match tree {
        Tree::Empty=>0,Tree::Node(left,right)=>1+tree_depth(left).max(tree_depth(right))
    }
}

