fn balanced(s: &str) -> bool {
    let mut depth=0;
    for ch in s.chars() {
        if ch=='(' {
            depth+=1;
        }
        else {
            depth-=1;
        }
        if depth<0 {
            return false;
        }
    }
    depth==0
}

